def transform_model2(grid):
    h,w=len(grid),len(grid[0]); r0,c0=next((r,c) for r in range(h) for c in range(w) if grid[r][c]==2)
    if c0==0: mode='identity'; a=[row[:] for row in grid]
    elif c0==w-1: mode='rev'; a=[row[::-1] for row in grid]
    elif r0==0: mode='transpose'; a=[list(row) for row in zip(*grid)]
    elif r0==h-1: mode='transpose_rev'; a=[list(row)[::-1] for row in zip(*grid)]
    else: raise ValueError
    H,W=len(a),len(a[0]); out=[row[:] for row in a]
    sy=next(y for y in range(H) if a[y][0]==2)
    bars=[x for x in range(1,W-1) if sum(a[y][x]==8 for y in range(H)) >= H/2]
    branches=[(sy,0,0)]
    for bi,x in enumerate(bars):
        holes=[y for y in range(H) if a[y][x]!=8]
        new=[]
        nextx=bars[bi+1]-1 if bi+1<len(bars) else W-1
        for py,px,lastsign in branches:
            md=min(abs(y-py) for y in holes)
            nearest=[y for y in holes if abs(y-py)==md]
            for y in nearest:
                for xx in range(px,x):
                    if out[py][xx]==0: out[py][xx]=2
                sign=(1 if y>py else -1 if y<py else 0)
                if sign:
                    opp=-sign; bound=y; k=y+opp
                    while 0<=k<H and a[k][x]==8:
                        bound=k; k+=opp
                    lo=min(py,y,bound); hi=max(py,y,bound)
                    for yy in range(lo,hi+1):
                        if out[yy][x-1]==0: out[yy][x-1]=2
                new.append((y,x,sign or lastsign))
            # Non-nearest openings on the opposite side of the source position form a side branch.
            if md>0:
                sign=1 if nearest[0]>py else -1 if nearest[0]<py else 0
                if sign:
                    for alt in holes:
                        if abs(alt-py)>md and (alt-py)*sign<0:
                            for xx in range(x-1,nextx+1):
                                if out[alt][xx]==0: out[alt][xx]=2
        branches=new
    for y,px,_ in branches:
        for xx in range(px,W):
            if out[y][xx]==0: out[y][xx]=2
    if mode=='identity': return out
    if mode=='rev': return [row[::-1] for row in out]
    trans=[list(row) for row in zip(*out)]
    return trans if mode=='transpose' else [row[::-1] for row in trans]

